def _parse_mapping_schema(schema: Mapping[str, Any], value: object) -> dict[str, Any]:
    """Parse and validate output against the complete caller JSON Schema mapping."""
    parsed = _parse_json_object(value)
    shallow_schema: dict[str, Any] = {"type": "object"}
    if "required" in schema:
        shallow_schema["required"] = schema["required"]
    if "properties" in schema:
        shallow_schema["properties"] = {
            name: ({"type": prop["type"]} if isinstance(prop, Mapping) and "type" in prop else {})
            for name, prop in schema["properties"].items()
        }
    Draft202012Validator(shallow_schema).validate(parsed)
    return parsed

def _parse_mapping_schema(schema: Mapping[str, Any], value: object) -> dict[str, Any]:
    """Parse and validate output against the complete caller JSON Schema mapping."""
    parsed = _parse_json_object(value)
    Draft202012Validator(dict(schema)).validate(parsed)
    properties = schema.get("properties")
    if isinstance(properties, Mapping):
        return {key: item for key, item in parsed.items() if key in properties}
    return parsed
